import * as React from "react"
import { Slot } from "@radix-ui/react-slot"

import { cn } from "@/lib/utils"

type ProseProps = React.ComponentProps<"article"> & {
  /** Set the child element (a div, say) instead of rendering an article. */
  asChild?: boolean
  /**
   * swiss (the default): space between paragraphs, punctuation hung in the margin. book: indents instead
   * of space, justified, the opening line in capitals, a dinkus for a break. run-on: a passage's paragraphs
   * run on as one block, a pilcrow where each begins.
   */
  variant?: "swiss" | "book" | "run-on"
}

/**
 * Long text, set to be read. Wrap plain HTML (headings, paragraphs, links, quotes, lists,
 * code, tables, rules) and it is styled by element, so rendered markdown needs no classes.
 */
function Prose({ asChild = false, variant = "swiss", className, ...props }: ProseProps) {
  const Comp = asChild ? Slot : "article"
  return <Comp data-slot="typography" data-variant={variant} className={cn("db-prose", className)} {...props} />
}

/** An opening paragraph, set at the lead size in ink. */
function ProseLead({ className, ...props }: React.ComponentProps<"p">) {
  return <p data-slot="typography-lead" className={cn("db-prose-lead", className)} {...props} />
}

export { Prose, ProseLead, type ProseProps }

@layer components {
  /* ── db-prose ── long text; punctuation hangs in the margin so the edge stays true */
  .db-prose { max-width: var(--db-measure); color: var(--db-graphite); hanging-punctuation: first last; }
  .db-prose > * + * { margin-top: 1em; }
  .db-prose > * + :is(h2, h3, h4, h5, h6) { margin-top: 1.8em; }
  .db-prose :is(h1, h2, h3, h4, h5, h6) { font-weight: 300; color: var(--db-ink); }
  .db-prose h1 { font-size: var(--db-ff); line-height: var(--db-ff-lh); letter-spacing: var(--db-ff-tr); }
  .db-prose h2 { font-size: var(--db-f); line-height: var(--db-f-lh); letter-spacing: var(--db-f-tr); }
  .db-prose h3 { font-size: var(--db-mf); line-height: var(--db-mf-lh); letter-spacing: var(--db-mf-tr); }
  .db-prose :is(h4, h5, h6) { font-size: var(--db-mp); line-height: var(--db-mp-lh); font-weight: 500; }
  .db-prose-lead { font-size: var(--db-mp); line-height: var(--db-mp-lh); color: var(--db-ink); text-wrap: balance; }
  .db-prose :is(h1, h2, h3, h4, h5, h6) { text-wrap: balance; }
  .db-prose :is(p, li) { text-wrap: pretty; }
  .db-prose blockquote { quotes: "“" "”"; font-family: var(--db-expression); font-style: italic; font-size: calc(var(--db-mp) * var(--db-expression-scale)); line-height: 1.35; color: var(--db-ink); }
  .db-prose blockquote > p { text-indent: -0.4em; } /* the opening mark hangs */
  .db-prose blockquote > p::before { content: open-quote; }
  .db-prose blockquote > p::after { content: close-quote; }
  .db-prose blockquote footer { margin-top: 0.6em; font-family: var(--db-voice); font-style: normal; font-size: var(--db-pp); color: var(--db-pencil); }
  .db-prose ul { list-style: none; padding: 0; }
  .db-prose ul > li { position: relative; }
  .db-prose ul > li::before { content: "–" / ""; position: absolute; inset-inline-start: -1.1em; color: var(--db-pencil); }
  .db-prose ol { padding: 0; padding-inline-start: 1.6em; list-style: decimal outside; } /* a number is too wide to hang: the list steps in, and the numbers stand on the edge */
  .db-prose ol > li::marker { color: var(--db-pencil); font-variant-numeric: tabular-nums; }
  .db-prose li + li { margin-top: 0.5em; } /* half a paragraph's pause, so a long item still reads as one */
  .db-prose code { font-family: var(--db-voice); font-stretch: 78%; font-weight: 500; letter-spacing: 0.01em; color: var(--db-ink); }
  .db-prose small { font-size: var(--db-pp); color: var(--db-pencil); }
  .db-prose > :first-child { margin-top: 0; }
  .db-prose strong { font-weight: 500; color: var(--db-ink); }
  .db-prose em { font-family: var(--db-expression); font-style: italic; font-size: calc(var(--db-expression-scale) * 1em); }
  .db-prose ul ul, .db-prose ol ol, .db-prose ul ol, .db-prose ol ul { margin-top: 0.35em; }
  .db-prose li > ul { padding-inline-start: 1.1em; } /* a nested list steps in by its dash, so the dash hangs under its parent's words */
  .db-prose hr { margin-block: 2em; }
  .db-prose img { display: block; max-inline-size: 100%; block-size: auto; }
  .db-prose figcaption { margin-top: 0.6em; font-size: var(--db-pp); line-height: var(--db-pp-lh); color: var(--db-pencil); }
  .db-prose pre {
    tab-size: 2; white-space: pre-wrap; overflow-wrap: anywhere; /* code wraps: nothing in the page scrolls sideways */
    font-family: var(--db-voice); font-stretch: 88%; font-size: 0.9375em; line-height: 1.7; letter-spacing: 0.005em;
    font-variant-numeric: tabular-nums lining-nums; color: var(--db-graphite);
  }
  .db-prose pre code { font: inherit; letter-spacing: inherit; color: inherit; }
  .db-prose table { width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums lining-nums; }
  .db-prose :is(th, td) { padding: var(--db-space-3) var(--db-space-4) var(--db-space-3) 0; text-align: start; vertical-align: baseline; border-bottom: var(--db-hairline) solid var(--db-rule); }
  .db-prose :is(th, td):last-child { padding-inline-end: 0; }
  .db-prose th { font-weight: 400; font-size: var(--db-pp); color: var(--db-pencil); }
  .db-prose thead th { padding-top: 0; border-bottom-color: var(--db-ink); white-space: nowrap; }

  /* book: the page of a book (Tschichold's Penguin rules; Bringhurst: indent or space, never both).
     Paragraphs follow on without a space, each indented an em and a half, the first after a heading flush;
     justified and hyphenated; the opening line set in spaced capitals; figures old style; a section break
     is a dinkus of three dots, not a rule. */
  .db-prose[data-variant="book"] > p { text-align: justify; hyphens: auto; font-variant-numeric: oldstyle-nums proportional-nums; }
  .db-prose[data-variant="book"] > p + p { margin-top: 0; text-indent: 1.5em; }
  .db-prose[data-variant="book"] > :is(h1, h2, h3, h4, h5, h6, hr) + p::first-line,
  .db-prose[data-variant="book"] > p:first-child::first-line { text-transform: uppercase; letter-spacing: 0.08em; font-size: 0.84em; color: var(--db-ink); }
  .db-prose[data-variant="book"] > :is(h1, h2, h3, h4, h5, h6) + .db-prose-lead::first-line { text-transform: none; letter-spacing: inherit; font-size: inherit; }
  .db-prose[data-variant="book"] > hr { height: auto; margin-block: 1.6em; background: none; text-align: center; color: var(--db-pencil); line-height: 1; }
  .db-prose[data-variant="book"] > hr::before { content: "·\2003·\2003·" / ""; font-size: var(--db-mf); }
  .db-prose[data-variant="book"] > blockquote { margin-inline: 1.5em; font-size: calc(var(--db-p) * var(--db-expression-scale)); }

  /* run-on: the scribe's paragraph. The paragraphs of a passage run on as one block, and where one
     ends a pilcrow stands in the line: the silence between paragraphs is kept as a single mark. */
  .db-prose[data-variant="run-on"] > p:not(.db-prose-lead) { display: inline; }
  .db-prose[data-variant="run-on"] > p:not(.db-prose-lead) + p:not(.db-prose-lead)::before {
    content: "\00b6" / ""; margin-inline: 0.35em 0.3em;
    font-family: var(--db-expression); font-style: normal; font-size: calc(var(--db-expression-scale) * 1.1em); line-height: 1; color: var(--db-ink);
  }
  .db-prose[data-variant="run-on"] > :not(p):has(+ p:not(.db-prose-lead)) { margin-bottom: 1em; } /* an inline paragraph takes no margin: what stands before it keeps the space */
  .db-prose[data-variant="run-on"] > p:not(.db-prose-lead) + :not(p) { margin-top: 1em; }
  .db-prose[data-variant="run-on"] > p:not(.db-prose-lead) + :is(h2, h3, h4, h5, h6) { margin-top: 1.8em; }
}
